using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and their impact on civilization." },
            new() { Id = 6, Name = "Biology", Code = "BIO", Description = "Study of living organisms and life processes." }
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Sarah Chen", Title = "Professor", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 papers and holds 3 patents in neural network architectures.", Email = "s.chen@university.edu", OfficeLocation = "Tech Building 301" },
            new() { Id = 2, Name = "Dr. James Wilson", Title = "Associate Professor", Bio = "Dr. Wilson's research focuses on distributed systems and cloud computing. He previously worked at major tech companies for 10 years.", Email = "j.wilson@university.edu", OfficeLocation = "Tech Building 205" },
            new() { Id = 3, Name = "Dr. Maria Garcia", Title = "Professor", Bio = "Dr. Garcia is an expert in abstract algebra and number theory with 20 years of teaching experience.", Email = "m.garcia@university.edu", OfficeLocation = "Science Hall 412" },
            new() { Id = 4, Name = "Dr. Robert Taylor", Title = "Assistant Professor", Bio = "Dr. Taylor researches quantum mechanics and particle physics. He completed postdoctoral work at CERN.", Email = "r.taylor@university.edu", OfficeLocation = "Physics Lab 102" },
            new() { Id = 5, Name = "Prof. Emily Brooks", Title = "Professor", Bio = "Prof. Brooks is an acclaimed author and literary critic specializing in 19th-century American literature.", Email = "e.brooks@university.edu", OfficeLocation = "Humanities 220" },
            new() { Id = 6, Name = "Dr. Michael Okafor", Title = "Associate Professor", Bio = "Dr. Okafor specializes in modern European history with a focus on post-war reconstruction.", Email = "m.okafor@university.edu", OfficeLocation = "Humanities 315" },
            new() { Id = 7, Name = "Dr. Lisa Patel", Title = "Professor", Bio = "Dr. Patel researches molecular biology and genetics. She leads the university's genomics lab.", Email = "l.patel@university.edu", OfficeLocation = "Life Sciences 401" },
            new() { Id = 8, Name = "Dr. David Kim", Title = "Assistant Professor", Bio = "Dr. Kim specializes in data structures and algorithm design. He is passionate about competitive programming.", Email = "d.kim@university.edu", OfficeLocation = "Tech Building 108" }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control structures, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00-9:50 AM", Room = "Tech 101", DepartmentId = 1, InstructorId = 2, IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
            new() { Id = 2, Code = "CS201", Title = "Data Structures & Algorithms", Description = "Study fundamental data structures (arrays, linked lists, trees, graphs) and algorithms (sorting, searching, dynamic programming). Prerequisites: CS101.", Credits = 4, Schedule = "Tue/Thu 10:30 AM-12:00 PM", Room = "Tech 205", DepartmentId = 1, InstructorId = 8, IsFeatured = true, MaxEnrollment = 80, CurrentEnrollment = 72 },
